package com.lamggm.rospocket;
import android.app.*;import android.view.*;import android.widget.*;import android.graphics.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31) @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class GaugeInputVisibilityTest extends GaugeActivityTest {
 @Test public void lightEditorKeepsInputForegroundContrastingWithItsSurface(){f.a.setTheme(R.style.AppTheme_Light);UiTheme.save(f.a,"light");f.a.applyAppearance();AlertDialog d=open();View decor=d.getWindow().getDecorView();for(String tag:new String[]{"display-path","display-min","display-max","display-unit"}){EditText e=decor.findViewWithTag(tag);assertEquals("Input foreground follows the explicit light palette",UiTheme.color(f.a,0xffe6edf3),e.getCurrentTextColor());assertNotEquals(UiTheme.color(f.a,0xff161d27),e.getCurrentTextColor());}}
 @Test public void populatedEditorFieldsActuallyPaintTextInsideTheirViewport()throws Exception{f.a.setTheme(R.style.AppTheme);UiTheme.save(f.a,"dark");f.a.applyAppearance();AlertDialog dialog=open();View decor=dialog.getWindow().getDecorView();decor.measure(View.MeasureSpec.makeMeasureSpec(1200,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1000,View.MeasureSpec.EXACTLY));decor.layout(0,0,1200,1000);for(String tag:new String[]{"display-path","display-min","display-max","display-unit"}){EditText e=decor.findViewWithTag(tag);assertNotEquals("Input text must not inherit the dialog surface colour",UiTheme.color(f.a,0xff161d27),e.getCurrentTextColor());e.setText(tag.equals("display-unit")?"m/s":tag.equals("display-path")?"data":"10.0");e.clearFocus();e.setCursorVisible(false);Bitmap actual=Bitmap.createBitmap(e.getWidth(),e.getHeight(),Bitmap.Config.ARGB_8888);e.draw(new Canvas(actual));String text=e.getText().toString();e.setText("");Bitmap empty=Bitmap.createBitmap(e.getWidth(),e.getHeight(),Bitmap.Config.ARGB_8888);e.draw(new Canvas(empty));int ink=0;for(int y=0;y<e.getHeight()-10;y++)for(int x=0;x<e.getWidth();x++)if(actual.getPixel(x,y)!=empty.getPixel(x,y))ink++;System.out.println(tag+" text="+text+" size="+e.getTextSize()+" height="+e.getHeight()+" pad="+e.getCompoundPaddingTop()+","+e.getCompoundPaddingBottom()+" baseline="+e.getBaseline()+" scroll="+e.getScrollY()+" ink="+ink);assertTrue("Typed text must paint inside "+tag+" (not just exist in accessibility), pixels="+ink,ink>30);e.setText(text);}}
}
